```cpp
template <typename T, size_t N>
struct StaticArray {
  T data[N];
  constexpr size_t size() const { return N; }
};

template <typename T, size_t N>
constexpr size_t arraySize(const StaticArray<T, N>& arr) {
  return arr.size();
}

int main() {
  StaticArray<int, 5> myArray;
  constexpr size_t size = arraySize(myArray); // size is known at compile time
  std::cout << size << std::endl; // Output: 5
  return 0;
}
