template <typename T, std::size_t N>
constexpr std::size_t factorial(std::size_t n) {
  return (n == 0) ? 1 : n * factorial(n - 1);
}
int main() {
  constexpr std::size_t result = factorial<int, 5>(5); //factorial computed at compile time
